action.mutation:
mutation UpdateInventoryCount($payload: [InventoryCountUpdatePayloadInput!]!) {
  mutation: updateInventoryCount(payload: $payload) { 
    id
    label
  }
}

mutation CreateInventoryCountSchedule($payload: [InventoryCountScheduleCreatePayloadInput!]!) {
  mutation: createInventoryCountSchedule(payload: $payload) { 
    id
    code
  }
}

mutation UpdateInventoryCountSchedule($payload: [InventoryCountScheduleUpdatePayloadInput!]!) {
  mutation: updateInventoryCountSchedule(payload: $payload) { 
    id
    code
  }
}

mutation DeleteInventoryCountSchedule($payload: [InventoryCountScheduleDeletePayloadInput!]!) {
  mutation: deleteInventoryCountSchedule(payload: $payload) { 
    id
    code
  }
}
